function ctrl = sht_load_controller_gain_schedule(ctrl)
%SHT_LOAD_CONTROLLER_GAIN_SCHEDULE Load controller coefficient schedule.
% The schedule is generated by Start_CtrlDesign_01_SteadyPointScheduleAnalysis.
% If scheduling is disabled, this function leaves ctrl unchanged.

if ~isstruct(ctrl) || ~isfield(ctrl, 'gainSchedule') || isempty(ctrl.gainSchedule)
    return;
end

gs = ctrl.gainSchedule;
if ~isfield(gs, 'enable') || ~gs.enable
    return;
end

if local_has_table(gs)
    ctrl.gainSchedule = local_normalize_table(gs);
    ctrl = local_repair_legacy_torque_gain(ctrl);
    return;
end

sourceFile = local_resolve_source_file(local_get_field(gs, 'sourceFile', ''));
if isempty(sourceFile) || ~exist(sourceFile, 'file')
    error('sht:gainSchedule:fileNotFound', ...
        'Controller gain schedule file not found: %s', sourceFile);
end

variableName = local_get_field(gs, 'variableName', 'gainSchedule');
data = load(sourceFile);
if isfield(data, variableName)
    loaded = data.(variableName);
elseif isfield(data, 'gainSchedule')
    loaded = data.gainSchedule;
else
    error('sht:gainSchedule:missingVariable', ...
        'Cannot find variable "%s" in %s.', variableName, sourceFile);
end

loaded.enable = true;
loaded.sourceFile = sourceFile;
loaded.variableName = variableName;
ctrl.gainSchedule = local_normalize_table(loaded);
ctrl = local_repair_legacy_torque_gain(ctrl);
end

function ctrl = local_repair_legacy_torque_gain(ctrl)
% 历史表曾将外部负载Mkp当作输出求导，因此整列d41错误为零。
% 在固定Np和负载条件下，轴动力学给出 d41/b11 = Jp*pi/30。
% 当前设计点直接差分已经使用PT驱动扭矩，取该比值恢复旧表；
% 不改变原文件及其他增益。非整列零的异常表不应擅自修复。
gs=ctrl.gainSchedule;
if all(isfinite(gs.d41)) && all(gs.d41==0)
    assert(isfield(ctrl,'linearModel') && ...
        isfield(ctrl.linearModel,'d41') && isfield(ctrl.linearModel,'b11'), ...
        'sht:gainSchedule:missingTorqueReference', ...
        '旧表d41为零且缺少当前轴动力学参考，不能启用扭矩保护。');
    factor=ctrl.linearModel.d41/ctrl.linearModel.b11;
    assert(isfinite(factor) && factor>0 && all(isfinite(gs.b11)) && all(gs.b11>0), ...
        'sht:gainSchedule:invalidTorqueReference','驱动扭矩灵敏度参考无效。');
    repair=struct('applied',true,'oldD41',gs.d41,'newD41',gs.b11*factor, ...
        'torquePerAcceleration',factor);
    ctrl.gainSchedule.d41=repair.newD41;
    ctrl.gainSchedule.torqueGainRepair=repair;
    fprintf('旧增益表d41已按轴动力学恢复，d41/b11=%.9g；原表未覆盖。\n',factor);
end
assert(all(isfinite(ctrl.gainSchedule.d41)) && all(ctrl.gainSchedule.d41>0), ...
    'sht:gainSchedule:invalidTorqueGain','d41必须为有效正驱动扭矩灵敏度。');
end

function tf = local_has_table(gs)
tf = isfield(gs, 'Ngc') && ~isempty(gs.Ngc) ...
    && isfield(gs, 'b11') && ~isempty(gs.b11) ...
    && isfield(gs, 'b21') && ~isempty(gs.b21) ...
    && isfield(gs, 'd31') && ~isempty(gs.d31) ...
    && isfield(gs, 'd41') && ~isempty(gs.d41);
end

function gs = local_normalize_table(gs)
names = {'Ngc', 'b11', 'b21', 'd31', 'd41'};
for i = 1:numel(names)
    name = names{i};
    gs.(name) = gs.(name)(:);
end
[ngc, order] = sort(gs.Ngc, 'ascend');
gs.Ngc = ngc;
for i = 2:numel(names)
    name = names{i};
    gs.(name) = gs.(name)(order);
end
if isfield(gs, 'pointName') && numel(gs.pointName) == numel(order)
    gs.pointName = gs.pointName(order);
end
if isfield(gs, 'pointIndex') && numel(gs.pointIndex) == numel(order)
    gs.pointIndex = gs.pointIndex(order);
end
gs.enable = local_get_field(gs, 'enable', true);
gs.independentVariable = local_get_field(gs, 'independentVariable', 'Ngc');
gs.interpolationMethod = local_get_field(gs, 'interpolationMethod', 'linear');
gs.extrapolationMode = local_get_field(gs, 'extrapolationMode', 'clamp');
end

function sourceFile = local_resolve_source_file(sourceFile)
if isempty(sourceFile)
    return;
end
if exist(sourceFile, 'file')
    return;
end
sourceFile = fullfile(fileparts(mfilename('fullpath')), sourceFile);
end

function value = local_get_field(s, name, defaultValue)
if isstruct(s) && isfield(s, name) && ~isempty(s.(name))
    value = s.(name);
else
    value = defaultValue;
end
end
